import selectors, socket

sel = selectors.DefaultSelector()
R = selectors.EVENT_READ
W = selectors.EVENT_WRITE
HIGH = 65536

def close(conn):
    sel.unregister(conn)
    conn.close()

def accept(lsock, mask):
    try:
        conn, _ = lsock.accept()
    except BlockingIOError:
        return
    conn.setblocking(False)
    out, eof = bytearray(), False

    def echo(conn, mask):
        nonlocal eof
        try:
            if mask & R and not eof:
                room = HIGH - len(out)
                if room:
                    try:
                        data = conn.recv(
                            min(4096, room))
                    except BlockingIOError:
                        data = None
                    if data == b"":
                        eof = True
                    elif data:
                        out.extend(data)
            if mask & W and out:
                try:
                    n = conn.send(out)
                except BlockingIOError:
                    n = None
                if n == 0:
                    close(conn)
                    return
                if n:
                    del out[:n]
        except OSError:
            close(conn)
            return
        events = W if out else 0
        if not eof and len(out) < HIGH:
            events |= R
        if events:
            sel.modify(conn, events, echo)
        else:
            close(conn)

    sel.register(conn, R, echo)

